m34 AS MATERIALIZED (SELECT DISTINCT d26."k0", d26."k1", r27."Date" AS v FROM (SELECT * FROM (SELECT DISTINCT t22."Region" AS "k0" FROM (SELECT region AS "Region", CAST(month || '-15' AS TIMESTAMP) AS "Date", amount AS "Amount" FROM read_json('tests/fixtures/sales_gap.json', columns = {region: 'VARCHAR', month: 'VARCHAR', amount: 'BIGINT'})) AS t22) AS c23 CROSS JOIN (SELECT DISTINCT t24."Month" AS "k1" FROM (SELECT d AS "Date", year(d) AS "Year", strftime(d, '%Y-%m') AS "Month" FROM generate_series(TIMESTAMP '2025-12-01', TIMESTAMP '2026-04-30', INTERVAL 1 DAY) AS t(d)) AS t24) AS c25) AS d26, LATERAL (SELECT s29."Date" FROM (SELECT DISTINCT t28."Date" FROM (SELECT d AS "Date", year(d) AS "Year", strftime(d, '%Y-%m') AS "Month" FROM generate_series(TIMESTAMP '2025-12-01', TIMESTAMP '2026-04-30', INTERVAL 1 DAY) AS t(d)) AS t28) AS s29 WHERE ((COALESCE(s29."Date", DATE '1899-12-30') >= COALESCE(CAST(date_trunc('year', (SELECT MAX(s31."Date") AS "v" FROM (SELECT DISTINCT t30."Date" FROM (SELECT d AS "Date", year(d) AS "Year", strftime(d, '%Y-%m') AS "Month" FROM generate_series(TIMESTAMP '2025-12-01', TIMESTAMP '2026-04-30', INTERVAL 1 DAY) AS t(d)) AS t30 WHERE t30."Month" IS NOT DISTINCT FROM d26."k1") AS s31)) AS DATE), DATE '1899-12-30')) AND (COALESCE(s29."Date", DATE '1899-12-30') <= COALESCE((SELECT MAX(s33."Date") AS "v" FROM (SELECT DISTINCT t32."Date" FROM (SELECT d AS "Date", year(d) AS "Year", strftime(d, '%Y-%m') AS "Month" FROM generate_series(TIMESTAMP '2025-12-01', TIMESTAMP '2026-04-30', INTERVAL 1 DAY) AS t(d)) AS t32 WHERE t32."Month" IS NOT DISTINCT FROM d26."k1") AS s33), DATE '1899-12-30')))) AS r27),
f3 AS (SELECT t2."Region" AS "g0", j4."Month" AS "g1", SUM(t2."Amount") AS "a0" FROM (SELECT region AS "Region", CAST(month || '-15' AS TIMESTAMP) AS "Date", amount AS "Amount" FROM read_json('tests/fixtures/sales_gap.json', columns = {region: 'VARCHAR', month: 'VARCHAR', amount: 'BIGINT'})) AS t2 LEFT JOIN (SELECT d AS "Date", year(d) AS "Year", strftime(d, '%Y-%m') AS "Month" FROM generate_series(TIMESTAMP '2025-12-01', TIMESTAMP '2026-04-30', INTERVAL 1 DAY) AS t(d)) AS j4 ON j4."Date" = t2."Date" GROUP BY t2."Region", j4."Month"),
f20 AS (SELECT t5."Region" AS "g0", m18."k1" AS "g1", SUM(t5."Amount") AS "a0" FROM (SELECT region AS "Region", CAST(month || '-15' AS TIMESTAMP) AS "Date", amount AS "Amount" FROM read_json('tests/fixtures/sales_gap.json', columns = {region: 'VARCHAR', month: 'VARCHAR', amount: 'BIGINT'})) AS t5 LEFT JOIN (SELECT d AS "Date", year(d) AS "Year", strftime(d, '%Y-%m') AS "Month" FROM generate_series(TIMESTAMP '2025-12-01', TIMESTAMP '2026-04-30', INTERVAL 1 DAY) AS t(d)) AS j19 ON j19."Date" = t5."Date" JOIN m18 ON m18.v = j19."Date" AND m18."k0" IS NOT DISTINCT FROM t5."Region" GROUP BY t5."Region", m18."k1"),
f36 AS (SELECT t21."Region" AS "g0", m34."k1" AS "g1", SUM(t21."Amount") AS "a0" FROM (SELECT region AS "Region", CAST(month || '-15' AS TIMESTAMP) AS "Date", amount AS "Amount" FROM read_json('tests/fixtures/sales_gap.json', columns = {region: 'VARCHAR', month: 'VARCHAR', amount: 'BIGINT'})) AS t21 LEFT JOIN (SELECT d AS "Date", year(d) AS "Year", strftime(d, '%Y-%m') AS "Month" FROM generate_series(TIMESTAMP '2025-12-01', TIMESTAMP '2026-04-30', INTERVAL 1 DAY) AS t(d)) AS j35 ON j35."Date" = t21."Date" JOIN m34 ON m34.v = j35."Date" AND m34."k0" IS NOT DISTINCT FROM t21."Region" GROUP BY t21."Region", m34."k1")
SELECT q43."Region" AS "Region", q43."Month" AS "Month", CAST(q43."revenue" AS BIGINT) AS "revenue", CAST(q43."prior" AS BIGINT) AS "prior", CAST(q43."to_date" AS BIGINT) AS "to_date" FROM (SELECT s42."Region", s42."Month", s42."revenue", s42."prior", s42."to_date" FROM (SELECT * FROM (SELECT k1."Region" AS "Region", k1."Month" AS "Month", f3.a0 AS "revenue", f20.a0 AS "prior", f36.a0 AS "to_date" FROM (SELECT * FROM (SELECT DISTINCT t37."Region" FROM (SELECT region AS "Region", CAST(month || '-15' AS TIMESTAMP) AS "Date", amount AS "Amount" FROM read_json('tests/fixtures/sales_gap.json', columns = {region: 'VARCHAR', month: 'VARCHAR', amount: 'BIGINT'})) AS t37) AS c39 CROSS JOIN (SELECT DISTINCT t38."Month" FROM (SELECT d AS "Date", year(d) AS "Year", strftime(d, '%Y-%m') AS "Month" FROM generate_series(TIMESTAMP '2025-12-01', TIMESTAMP '2026-04-30', INTERVAL 1 DAY) AS t(d)) AS t38) AS c40) AS k1 LEFT JOIN f3 ON f3.g0 IS NOT DISTINCT FROM k1."Region" AND f3.g1 IS NOT DISTINCT FROM k1."Month" LEFT JOIN f20 ON f20.g0 IS NOT DISTINCT FROM k1."Region" AND f20.g1 IS NOT DISTINCT FROM k1."Month" LEFT JOIN f36 ON f36.g0 IS NOT DISTINCT FROM k1."Region" AND f36.g1 IS NOT DISTINCT FROM k1."Month") AS z41 WHERE z41."revenue" IS NOT NULL OR z41."prior" IS NOT NULL OR z41."to_date" IS NOT NULL) AS s42) AS q43 ORDER BY q43."Region" ASC NULLS FIRST, q43."Month" ASC NULLS FIRST
)
SELECT list({region: "Region", month: "Month", revenue: revenue, prior: prior, to_date: to_date} ORDER BY "Region", "Month") AS result FROM dax WHERE revenue IS NOT NULL;
